@startuml

class Cinema {
  + Name : string
  + Town : string
}

class Theatre {
  + Name : string
}

class Movie {
  + Name : string
}

class MovieCopy {
}

class Show {
  + StartTime : datetime
  + EndTime : datetime
  + publish()
  + cancelShow()
}

class Reservation {
  + ReservationTime : datetime
  + isCancelled : boolean
}

class AlternativeOffer {
  + expire()
  + accept()
  + decline()
}

class Ticket {
  + SeatNumber : string
}

class Customer {
  + Name : string
}

class CreditCard {
  + CardNumber : string
}

Cinema "1" *-- "1..*" Theatre
Cinema "1" -- "0..*" MovieCopy
Movie "1" -- "0..*" MovieCopy
MovieCopy "1" -- "0..*" Show
Theatre "1" -- "0..*" Show
Show "1" -- "0..*" Reservation
Show "1" -- "0..*" Ticket
Show "1" -- "0..*" AlternativeOffer
Reservation "0..1" -- "1" Customer
Reservation "1" -- "1" CreditCard
Ticket "0..*" -- "1" Customer
Ticket "0..*" -- "1" Show

@enduml

